/**
 * Logo da LPX Tech usada no PDF do orçamento.
 *
 * Embutida como data URI de propósito: o @react-pdf/renderer roda no
 * navegador e um arquivo externo dependeria de fetch (e do basePath
 * /hertz-wo) para o PDF sair com a marca. Gerada a partir de
 * "LPX Tech completa.png" (1104x462), reduzida para 700px e paletizada
 * em 256 cores sobre fundo branco — o PDF é branco, então o alpha não
 * faz falta e o arquivo cai de 200 KB para ~39 KB.
 */
export const LPX_LOGO_PNG =
  "data:image/png;base64,";

/** Proporção original: 1104x462. */
export const LPX_LOGO_RATIO = 1104 / 462;

/**
 * Assinatura usada no recibo, embutida pelo mesmo motivo da logo.
 * Gerada de "Assinatura lucas.png" (1123x228), reduzida para 620px e
 * paletizada em 64 cores sobre branco: 160 KB -> 12 KB.
 */
export const LPX_ASSINATURA_PNG =
  "data:image/png;base64,";

/** Proporção original da assinatura: 1123x228. */
export const LPX_ASSINATURA_RATIO = 1123 / 228;

/** Quem assina os recibos. */
export const LPX_SIGNATARIO = "Lucas Alexandre Piovezan";
export const LPX_EMPRESA = "LPX Tech";
export const LPX_RAMO = "Manutenção Eletrônica";

/**
 * Logo curta usada no cabeçalho da sidebar (não no PDF).
 *
 * Duas variantes porque o arquivo original tem o "LPX" preto sobre fundo
 * transparente: no tema escuro ele sumiria. A variante escura clareia só os
 * pixels acinzentados e preserva o X laranja/azul e o "Tech".
 * Gerada de "LPX Tech.png" (1104x242), reduzida para 260px.
 */
export const LPX_LOGO_CURTA_LIGHT =
  "data:image/png;base64,";

export const LPX_LOGO_CURTA_DARK =
  "data:image/png;base64,";

/** Proporção da logo curta: 1104x242. */
export const LPX_LOGO_CURTA_RATIO = 1104 / 242;
